import{_ as t,o as a,c as o,ag as l}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/docs-editor/write-a-proposal-final.png",g=JSON.parse('{"title":"Write a project proposal","description":"Build a one-page project proposal with a title, headings, a list, a budget table, an image, a link, and page numbers.","frontmatter":{"title":"Write a project proposal","description":"Build a one-page project proposal with a title, headings, a list, a budget table, an image, a link, and page numbers.","type":"tutorial"},"headers":[],"relativePath":"docs-editor/write-a-proposal.md","filePath":"docs-editor/write-a-proposal.md"}'),i={name:"docs-editor/write-a-proposal.md"};function r(n,e,d,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[l(`<h1 id="write-a-project-proposal" tabindex="-1">Write a project proposal <a class="header-anchor" href="#write-a-project-proposal" aria-label="Permalink to &quot;Write a project proposal&quot;">​</a></h1><p>You will build a short project proposal with a title, section headings, a bulleted list, a budget table with a shaded header row, an image, a link, and a page number in the footer. It takes about 10 minutes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be a member of a workspace.</li><li>Use a computer. A few steps (the table size picker, the footer) are easier with a mouse.</li><li>Have a PNG or JPEG image on hand, such as a logo or a chart.</li></ul></div><h2 id="_1-create-the-document-and-add-a-title" tabindex="-1">1. Create the document and add a title <a class="header-anchor" href="#_1-create-the-document-and-add-a-title" aria-label="Permalink to &quot;1. Create the document and add a title&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong> and select <strong>New document</strong>.</li><li>Click the title in the header, type <code>Project proposal</code>, and press <code>Enter</code>.</li><li>Click the page and type <code>Website redesign proposal</code>.</li><li>Open the <strong>Styles</strong> dropdown at the left of the toolbar (it shows <strong>Normal text</strong>) and select <strong>Title</strong>.</li><li>Press <code>Enter</code> to start a new line. The new line is <strong>Normal text</strong> again.</li></ol><h2 id="_2-add-sections-and-a-list" tabindex="-1">2. Add sections and a list <a class="header-anchor" href="#_2-add-sections-and-a-list" aria-label="Permalink to &quot;2. Add sections and a list&quot;">​</a></h2><ol><li><p>Type <code>#</code> and press <code>Space</code>. The line becomes <strong>Heading 1</strong>.</p></li><li><p>Type <code>Goals</code> and press <code>Enter</code>.</p></li><li><p>Type <code>-</code> and press <code>Space</code> to start a bulleted list, then type these items, pressing <code>Enter</code> after each:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cut page load time in half</span></span>
<span class="line"><span>Make every page work on a phone</span></span>
<span class="line"><span>Launch before the end of the quarter</span></span></code></pre></div></li><li><p>Press <code>Enter</code> on the empty bullet to end the list.</p></li><li><p>Type <code>#</code>, press <code>Space</code>, type <code>Budget</code>, and press <code>Enter</code>.</p></li></ol><p>You now have two Heading 1 sections. Headings show up as larger, bold text.</p><h2 id="_3-insert-and-shade-a-budget-table" tabindex="-1">3. Insert and shade a budget table <a class="header-anchor" href="#_3-insert-and-shade-a-budget-table" aria-label="Permalink to &quot;3. Insert and shade a budget table&quot;">​</a></h2><ol><li><p>Click the <strong>Insert table</strong> button (grid icon) in the toolbar.</p></li><li><p>Move the pointer over the grid until the label under it reads <code>4 x 3</code> (4 rows, 3 columns), then click.</p></li><li><p>Type the table below. Press <code>Tab</code> to move to the next cell.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Item          Owner   Cost</span></span>
<span class="line"><span>Design        Alice   $12,000</span></span>
<span class="line"><span>Development   Bob     $30,000</span></span>
<span class="line"><span>Testing       Carol   $6,000</span></span></code></pre></div></li><li><p>Drag from the first cell to the last cell of the top row to select the header row.</p></li><li><p>Right-click the selection, select <strong>Cell background</strong>, and click a light gray swatch.</p></li><li><p>Click below the table to leave it.</p></li></ol><p>The header row is shaded and the costs line up in their own column.</p><h2 id="_4-add-an-image-and-a-link" tabindex="-1">4. Add an image and a link <a class="header-anchor" href="#_4-add-an-image-and-a-link" aria-label="Permalink to &quot;4. Add an image and a link&quot;">​</a></h2><ol><li>Put the cursor on an empty line below the table.</li><li>Click <strong>Insert image</strong> (picture icon) and select <strong>Upload from computer</strong>, then choose your image.</li><li>Click the image and drag a corner handle to make it about half the page width.</li><li>Click after the image, press <code>Enter</code>, and type <code>See the current site for comparison.</code></li><li>Select the words <code>current site</code>, press <code>⌘+K</code> / <code>Ctrl+K</code>, type <code>https://example.com</code>, and click <strong>Apply</strong>.</li></ol><p>The words become a link. Put the cursor in them to see the address.</p><h2 id="_5-number-the-pages-and-switch-to-a4" tabindex="-1">5. Number the pages and switch to A4 <a class="header-anchor" href="#_5-number-the-pages-and-switch-to-a4" aria-label="Permalink to &quot;5. Number the pages and switch to A4&quot;">​</a></h2><ol><li>Scroll to the bottom of the page and double-click the margin below the text. The footer opens, and the toolbar narrows to footer controls.</li><li>Click <strong>Page number</strong> in the toolbar. A page number appears in the footer.</li><li>Press <code>Escape</code> to return to the body.</li><li>Click <strong>Page setup</strong> (page icon) at the right end of the toolbar.</li><li>Set <strong>Paper size</strong> to <strong>A4</strong> and click <strong>Apply</strong>.</li></ol><h2 id="check-your-work" tabindex="-1">Check your work <a class="header-anchor" href="#check-your-work" aria-label="Permalink to &quot;Check your work&quot;">​</a></h2><p>Your proposal should look like this: a title, two headings, a list, a shaded table, an image, a link, and a page number at the bottom of the A4 page.</p><p><img src="`+s+'" alt="Finished proposal with a title, Goals list, budget table with a gray header row, an image, and a footer page number"></p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li>Markdown-style shortcuts (<code>#</code> and <code>-</code> followed by <code>Space</code>) turn lines into headings and lists as you type.</li><li>Tables take <code>Tab</code> to move between cells, and right-click for cell colors.</li><li>Headers, footers, and page setup apply to the whole document.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/collaborate/share.html">Share a document</a> to ask teammates for feedback.</li><li><a href="/docs/files/import-export.html">Import and export</a> to download the proposal as a PDF or Word file.</li><li><a href="/docs/docs-editor/format-text.html">Format text</a> to redefine how your headings look across the document.</li><li><a href="/docs/collaborate/comments.html">Comments</a> to collect review notes on specific lines.</li></ul>',23)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
